(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-504":{scenario:{company:"Sóng Việt Fitness Chain",supervisor:{name:"Mai Hoàng Yến",role:{vi:"Giám đốc Pháp chế & Bảo vệ dữ liệu",en:"Director of Legal & Data Protection"}},ref_code:"INC-1108",title:{vi:"Đúng phân loại. Đúng số chủ thể. Đúng hạn thông báo.",en:"Right classification. Right data subjects. Right notice."},brief:{vi:"Đây là tình huống đào tạo. Chuỗi phòng tập phát hiện sự cố lộ dữ liệu hội viên từ máy chủ nhận diện khuôn mặt khi check-in, hồ sơ INC-1108. Nhật ký trích xuất có 12486 bản ghi, trong đó 2118 bản ghi trùng của cùng hội viên và 352 tài khoản thử nghiệm nội bộ không phải người thật. Bản nháp xếp mẫu khuôn mặt là dữ liệu cơ bản và báo cáo theo số bản ghi. Hãy sửa phân loại dữ liệu và số chủ thể bị ảnh hưởng, rồi lập báo cáo sự cố có căn cứ.",en:"This is a training scenario. The gym chain has detected a leak of member data from the face recognition check-in server, incident file INC-1108. The extraction log shows 12486 records, of which 2118 are duplicates of the same members and 352 are internal test accounts that are not real people. The draft treats face templates as basic data and reports the record count. Correct the data classification and the number of affected data subjects, then write an evidence-based incident report."},reference_title:{vi:"Sổ đăng ký hoạt động xử lý & nhật ký sự cố đã duyệt · INC-1108",en:"Approved record of processing & incident log · INC-1108"},fields:[{id:"DATA_CLASS",label:{vi:"Phân loại mẫu khuôn mặt",en:"Face template classification"},initial:"PD-BASIC",expected:"PD-SENSITIVE",choices:["PD-BASIC","PD-SENSITIVE","PD-ANON"],reference:"Danh mục phân loại dữ liệu cá nhân",hint:{vi:"Dữ liệu sinh trắc học dùng để nhận dạng một con người cụ thể không phải dữ liệu cơ bản.",en:"Biometric data used to identify a specific person is not basic personal data."}},{id:"SUBJECTS",label:{vi:"Số chủ thể dữ liệu bị ảnh hưởng",en:"Affected data subjects"},initial:"12486",expected:"10016",reference:"Nhật ký trích xuất sự cố",ref_value:{vi:"12486 bản ghi; 2118 bản ghi trùng; 352 tài khoản thử nghiệm",en:"12486 records; 2118 duplicates; 352 test accounts"},hint:{vi:"Đếm người thật duy nhất bị ảnh hưởng, không đếm số dòng dữ liệu.",en:"Count unique real people affected, not rows of data."}}],sop32:{vi:"Số chủ thể bị ảnh hưởng = tổng bản ghi bị lộ - bản ghi trùng của cùng chủ thể - tài khoản thử nghiệm không phải người thật; con số này dùng cho thông báo vi phạm trong 72 giờ.",en:"Affected data subjects = total leaked records - duplicate records of the same person - test accounts that are not real people; this figure is used in the 72-hour breach notice."},context:{label:"PRIVACY OPS / INC-1108",metrics:[{label:{vi:"Bản ghi bị lộ",en:"Leaked records"},value:"12486"},{label:{vi:"Bản ghi trùng",en:"Duplicate records"},value:"2118"},{label:{vi:"Tài khoản thử nghiệm",en:"Test accounts"},value:"352"},{label:{vi:"Đã trôi qua từ khi phát hiện",en:"Time since detection"},value:"19 h / 72 h"}]},crisis:{vi:"Giám đốc Marketing nhắn: “Đừng báo cơ quan chức năng hay hội viên vội, tuần sau mình ra mắt gói hội viên mới. Cứ âm thầm vá lỗi, xóa bớt nhật ký truy cập rồi tính sau.”",en:"The Marketing Director messages: “Don't notify the authority or members yet, we launch the new membership plan next week. Patch it quietly, trim the access logs and we'll see later.”"},options:{safe:{vi:"Từ chối che giấu và xóa nhật ký, báo ngay Tổng giám đốc và Giám đốc Pháp chế, chuẩn bị thông báo cơ quan chuyên trách đúng hạn 72 giờ, bảo toàn chứng cứ và hướng dẫn hội viên giảm thiểu rủi ro.",en:"Refuse to conceal the breach or delete logs, inform the CEO and the Legal Director at once, prepare the notice to the competent authority within 72 hours, preserve evidence and guide members on mitigation."},shortcut:{vi:"Vá lỗi, xóa bớt nhật ký và chờ sau đợt ra mắt mới thông báo.",en:"Patch the flaw, trim the logs and notify only after the launch."},wait:{vi:"Không làm gì cho tới khi có người hỏi đến sự cố.",en:"Do nothing until someone asks about the incident."}},questions:{vi:["Vì sao mẫu khuôn mặt là dữ liệu cá nhân nhạy cảm và việc phân loại sai ảnh hưởng thế nào đến biện pháp bảo vệ, nghĩa vụ đánh giá tác động?","Trình bày cách bạn xác định số chủ thể bị ảnh hưởng và trình tự thông báo vi phạm trong 72 giờ, kể cả khi bị yêu cầu trì hoãn."],en:["Why are face templates sensitive personal data, and how does misclassification affect safeguards and impact assessment duties?","Explain how you determined the number of affected data subjects and the 72-hour breach notification sequence, even under pressure to delay."]},hints:{vi:["Đối chiếu loại dữ liệu trong sổ đăng ký hoạt động xử lý với danh mục dữ liệu nhạy cảm.","Loại bản ghi trùng và tài khoản thử nghiệm khỏi tổng số trước khi báo cáo theo SOP mục 3.2.","Đọc lại SOP mục 4.2: không được che giấu sự cố hay xóa nhật ký; mọi áp lực trì hoãn phải được báo cáo."],en:["Match the data type in the record of processing against the sensitive data list.","Remove duplicates and test accounts from the total before reporting, as SOP 3.2 requires.","Re-read SOP 4.2: never hide an incident or delete logs; any pressure to delay must be escalated."]}},learning:{summary:{vi:"Chuyên viên Bảo vệ Dữ liệu Cá nhân thiết kế và vận hành chương trình tuân thủ quyền riêng tư của tổ chức: lập sổ đăng ký hoạt động xử lý, đánh giá tác động, quản lý sự đồng ý, xử lý yêu cầu của chủ thể dữ liệu, kiểm soát bên xử lý và ứng phó sự cố. Nghề kết hợp hiểu biết pháp luật Việt Nam và GDPR với kiến thức an toàn thông tin, đòi hỏi bản lĩnh nói không với việc che giấu vi phạm.",en:"A Data Privacy Officer designs and runs the organization's privacy compliance program: records of processing, impact assessments, consent management, data subject requests, processor oversight and incident response. The role combines Vietnamese law and GDPR with information security knowledge and requires the courage to say no to hiding breaches."},responsibilities:{vi:["Lập và cập nhật sổ đăng ký hoạt động xử lý, phân loại dữ liệu cơ bản và nhạy cảm.","Thực hiện đánh giá tác động xử lý dữ liệu cá nhân (DPIA) cho hệ thống, dự án mới.","Xây dựng chính sách quyền riêng tư, cơ chế thu thập và rút lại sự đồng ý.","Tiếp nhận, xử lý yêu cầu truy cập, chỉnh sửa, xóa dữ liệu của chủ thể đúng hạn.","Điều phối ứng phó sự cố, thông báo vi phạm và đào tạo nhận thức cho nhân viên."],en:["Build and maintain the record of processing and classify basic and sensitive data.","Carry out data protection impact assessments (DPIA) for new systems and projects.","Develop privacy notices and mechanisms to collect and withdraw consent.","Receive and handle access, correction and deletion requests from data subjects on time.","Coordinate incident response and breach notification and train staff on awareness."]},competencies:[{name:{vi:"Phân tích pháp lý quyền riêng tư",en:"Privacy legal analysis"},desc:{vi:"Áp dụng đúng quy định Việt Nam và GDPR về căn cứ xử lý, dữ liệu nhạy cảm, chuyển dữ liệu ra nước ngoài.",en:"Apply Vietnamese rules and GDPR correctly on legal bases, sensitive data and cross-border transfers."}},{name:{vi:"Lập bản đồ dữ liệu",en:"Data mapping"},desc:{vi:"Xác định dữ liệu gì, ở đâu, ai truy cập, lưu bao lâu và luồng chia sẻ cho bên thứ ba.",en:"Identify what data exists, where, who accesses it, how long it is kept and how it flows to third parties."}},{name:{vi:"Đánh giá rủi ro",en:"Risk assessment"},desc:{vi:"Đánh giá tác động tới chủ thể dữ liệu và đề xuất biện pháp kỹ thuật, tổ chức tương xứng.",en:"Assess impact on data subjects and propose proportionate technical and organizational measures."}},{name:{vi:"Ứng phó sự cố",en:"Incident response"},desc:{vi:"Khoanh vùng, xác định phạm vi, đếm đúng chủ thể bị ảnh hưởng và thông báo trong thời hạn.",en:"Contain, scope the breach, count affected subjects accurately and notify within the deadline."}},{name:{vi:"Độc lập & chính trực",en:"Independence & integrity"},desc:{vi:"Báo cáo trực tiếp lãnh đạo cao nhất, không để áp lực kinh doanh làm sai lệch nghĩa vụ pháp lý.",en:"Report to top management and never let business pressure distort legal obligations."}}],knowledge:{vi:["Nghị định 13/2023/NĐ-CP về bảo vệ dữ liệu cá nhân: dữ liệu cơ bản, nhạy cảm, thông báo vi phạm trong 72 giờ.","Luật Bảo vệ dữ liệu cá nhân năm 2025 (hiệu lực từ 01/01/2026) và văn bản hướng dẫn.","GDPR (Quy định EU 2016/679): Điều 6 căn cứ xử lý, Điều 9 dữ liệu đặc biệt, Điều 33 thông báo 72 giờ, Điều 35 DPIA.","ISO/IEC 27001 và ISO/IEC 27701 về hệ thống quản lý an toàn thông tin và quyền riêng tư.","Nguyên tắc privacy by design, tối thiểu hóa dữ liệu, giới hạn mục đích và thời hạn lưu trữ."],en:["Decree 13/2023/ND-CP on personal data protection: basic and sensitive data, 72-hour breach notification.","The 2025 Law on Personal Data Protection (effective 1 January 2026) and its guiding documents.","GDPR (Regulation (EU) 2016/679): Article 6 legal bases, Article 9 special categories, Article 33 72-hour notice, Article 35 DPIA.","ISO/IEC 27001 and ISO/IEC 27701 on information security and privacy management systems.","Privacy by design, data minimization, purpose limitation and storage limitation principles."]},tools:["Phần mềm quản trị quyền riêng tư (DPIA)","Nền tảng quản lý sự đồng ý","Công cụ khám phá & phân loại dữ liệu","Hệ thống SIEM và nhật ký truy cập","Mẫu thông báo vi phạm & quy trình ứng phó"],kpis:{vi:["Tỷ lệ hệ thống có trong sổ đăng ký hoạt động xử lý và đã đánh giá tác động.","Tỷ lệ yêu cầu của chủ thể dữ liệu xử lý đúng hạn.","Tỷ lệ sự cố được thông báo trong thời hạn luật định (mục tiêu 100%).","Tỷ lệ nhân viên hoàn thành đào tạo bảo vệ dữ liệu hằng năm."],en:["Share of systems listed in the record of processing with a completed impact assessment.","Share of data subject requests handled on time.","Share of incidents notified within the legal deadline (target 100%).","Share of staff completing annual data protection training."]},day:[{time:"08:30",vi:"Rà cảnh báo an ninh và hộp thư yêu cầu của chủ thể dữ liệu.",en:"Review security alerts and the data subject request inbox."},{time:"10:00",vi:"Họp nhóm sản phẩm để đánh giá tác động cho tính năng nhận diện khuôn mặt mới.",en:"Meet the product team on an impact assessment for a new face recognition feature."},{time:"13:30",vi:"Rà hợp đồng xử lý dữ liệu với nhà cung cấp điện toán đám mây.",en:"Review the data processing agreement with a cloud provider."},{time:"15:30",vi:"Diễn tập ứng phó sự cố với IT và Pháp chế, kiểm tra mẫu thông báo 72 giờ.",en:"Run an incident drill with IT and Legal and test the 72-hour notice template."},{time:"17:00",vi:"Cập nhật sổ đăng ký hoạt động xử lý và báo cáo rủi ro cho ban điều hành.",en:"Update the record of processing and report risks to management."}],mistakes:{vi:["Xếp dữ liệu sinh trắc học, sức khỏe, vị trí vào nhóm dữ liệu cơ bản.","Báo cáo số bản ghi thay vì số chủ thể dữ liệu duy nhất bị ảnh hưởng.","Trì hoãn thông báo vi phạm hoặc xóa nhật ký theo yêu cầu kinh doanh."],en:["Treating biometric, health or location data as basic data.","Reporting the number of records instead of unique affected data subjects.","Delaying breach notification or deleting logs at business request."]},career:[{vi:"Chuyên viên tuân thủ quyền riêng tư",en:"Privacy compliance analyst"},{vi:"Chuyên viên bảo vệ dữ liệu cá nhân",en:"Data protection specialist"},{vi:"Cán bộ bảo vệ dữ liệu (DPO)",en:"Data Protection Officer (DPO)"},{vi:"Giám đốc Quyền riêng tư (Chief Privacy Officer)",en:"Chief Privacy Officer"}],glossary:[{term:"Dữ liệu cá nhân nhạy cảm",vi:"Dữ liệu gắn với quyền riêng tư mà khi bị xâm phạm ảnh hưởng trực tiếp tới quyền, lợi ích của cá nhân, như sinh trắc học, sức khỏe.",en:"Sensitive personal data: data whose breach directly harms a person's rights, such as biometrics or health."},{term:"Chủ thể dữ liệu",vi:"Cá nhân được dữ liệu cá nhân phản ánh, người có các quyền đối với dữ liệu của mình.",en:"Data subject: the individual the personal data relates to, who holds rights over that data."},{term:"DPIA",vi:"Đánh giá tác động xử lý dữ liệu cá nhân, nhận diện rủi ro và biện pháp giảm thiểu trước khi xử lý.",en:"Data protection impact assessment identifying risks and mitigations before processing begins."},{term:"Bên xử lý dữ liệu",vi:"Tổ chức xử lý dữ liệu thay mặt bên kiểm soát theo hợp đồng, ví dụ nhà cung cấp đám mây.",en:"Data processor: an organization processing data on the controller's behalf under contract, such as a cloud vendor."},{term:"Privacy by design",vi:"Tích hợp bảo vệ dữ liệu ngay từ thiết kế hệ thống và quy trình, không chờ đến khi vận hành.",en:"Building data protection into systems and processes from the design stage, not after go-live."}],quiz:[{q:{vi:"Theo GDPR, bên kiểm soát phải thông báo vi phạm dữ liệu cho cơ quan giám sát trong thời hạn nào kể từ khi biết?",en:"Under GDPR, within what time must a controller notify a breach to the supervisory authority after becoming aware?"},options:{vi:["24 giờ","72 giờ","7 ngày","30 ngày"],en:["24 hours","72 hours","7 days","30 days"]},answer:1,explain:{vi:"Điều 33 GDPR yêu cầu thông báo không chậm trễ và trong vòng 72 giờ nếu khả thi; Nghị định 13/2023/NĐ-CP cũng quy định 72 giờ.",en:"GDPR Article 33 requires notice without undue delay and within 72 hours where feasible; Decree 13/2023/ND-CP also sets 72 hours."}},{q:{vi:"Loại dữ liệu nào sau đây là dữ liệu cá nhân nhạy cảm?",en:"Which of the following is sensitive personal data?"},options:{vi:["Họ và tên","Số điện thoại","Mẫu sinh trắc học khuôn mặt","Email công việc"],en:["Full name","Phone number","Biometric face template","Work email"]},answer:2,explain:{vi:"Dữ liệu sinh trắc học dùng để nhận dạng cá nhân thuộc nhóm nhạy cảm và cần biện pháp bảo vệ tăng cường.",en:"Biometric data used to identify a person is sensitive and needs enhanced safeguards."}},{q:{vi:"Lãnh đạo kinh doanh đề nghị hoãn thông báo vi phạm tới sau đợt ra mắt sản phẩm. Bạn làm gì?",en:"A business leader asks to delay breach notification until after a product launch. What do you do?"},options:{vi:["Đồng ý vì chỉ chậm vài ngày","Chỉ báo hội viên, không báo cơ quan","Xóa bớt nhật ký cho gọn","Từ chối, báo lãnh đạo cao nhất và thông báo đúng hạn, lưu hồ sơ"],en:["Agree since it is only a few days","Tell members only, not the authority","Trim the logs","Refuse, escalate to top management and notify on time with records"]},answer:3,explain:{vi:"Thời hạn thông báo là nghĩa vụ pháp lý; trì hoãn hay xóa chứng cứ làm tăng thiệt hại và trách nhiệm.",en:"The deadline is a legal duty; delay or deleting evidence increases harm and liability."}},{q:{vi:"Sự cố có 5000 bản ghi, 600 bản ghi trùng cùng người và 150 tài khoản thử nghiệm. Có bao nhiêu chủ thể bị ảnh hưởng?",en:"An incident has 5000 records, 600 duplicates of the same people and 150 test accounts. How many data subjects are affected?"},options:{vi:["4250","4400","4850","5000"],en:["4250","4400","4850","5000"]},answer:0,explain:{vi:"5000 - 600 - 150 = 4250 người thật duy nhất.",en:"5000 - 600 - 150 = 4250 unique real people."}}],tools_en:["Privacy management software (DPIA)","Consent management platform","Data discovery & classification tool","SIEM and access logs","Breach notification templates & response plan"]}}})})(window.KKR);
